/** A transport producer that cannot touch its source before ownership handoff. */
export class PreparedStream {
    source;
    state = "pending";
    wake;
    ready = new Promise((resolve) => {
        this.wake = resolve;
    });
    iterator;
    busy = false;
    constructor(source) {
        this.source = source;
    }
    get pending() {
        return this.state === "pending";
    }
    commit() {
        if (this.state !== "pending")
            throw new Error("stream preparation is no longer pending");
        this.state = "committed";
        this.wake();
    }
    abort() {
        if (this.state !== "pending")
            return;
        this.state = "aborted";
        this.wake();
    }
    [Symbol.asyncIterator]() {
        return this;
    }
    async next() {
        if (this.busy)
            throw new Error("a stream read is already in progress");
        this.busy = true;
        try {
            await this.ready;
            if (this.state !== "committed")
                return { done: true, value: undefined };
            this.iterator ??= this.source[Symbol.asyncIterator]();
            return await this.iterator.next();
        }
        finally {
            this.busy = false;
        }
    }
    async return() {
        const committed = this.state === "committed";
        this.state = "closed";
        this.wake();
        if (committed) {
            this.iterator ??= this.source[Symbol.asyncIterator]();
            await this.iterator.return?.();
        }
        return { done: true, value: undefined };
    }
}
