import { Context, Layer } from "effect";
import * as AgentHost from "golem:agent/host@2.0.0";
export class ConfigClient extends Context.Service()("effect-golem/host/Config") {
}
export const ConfigLive = Layer.succeed(ConfigClient, ConfigClient.of({
    getConfigValue: (key, expected) => AgentHost.getConfigValue([...key], expected),
}));
