/**
 * @since 1.5.0
 */
import { Effect, Schema, SchemaGetter } from "effect";
import { composeSchemaGraphs } from "./internal/schema-model/builder.js";
import { emptyMetadata, t, v, variantCase, } from "./internal/schema-model/model.js";
import { isElementSpec, UnstructuredBinary, UnstructuredText, } from "./Unstructured.js";
import { toWitCodec } from "./WitCodec.js";
const MULTIMODAL_ROLE = { tag: "multimodal" };
const compileMember = (caseName, member) => Effect.gen(function* () {
    if (isElementSpec(member)) {
        return {
            name: caseName,
            graph: member.witCodec.graph,
            toValue: (domain) => Effect.sync(() => member.toValue(domain)),
            fromValue: (sv) => Effect.sync(() => member.fromValue(sv)),
        };
    }
    const wc = yield* toWitCodec(member);
    return {
        name: caseName,
        graph: wc.graph,
        toValue: (domain) => Schema.encodeEffect(wc.codec)(domain),
        fromValue: (sv) => Schema.decodeEffect(wc.codec)(sv),
    };
});
/**
 * Construct a multimodal element that accepts a named, ordered, repeatable
 * sequence of typed sub-elements.
 *
 * **Example**
 *
 * ```ts
 * const Content = multimodal({
 *   text:  UnstructuredText(),
 *   image: UnstructuredBinary(),
 *   meta:  Schema.Struct({ prompt: Schema.String }),
 * })
 * ```
 *
 * @since 1.5.0
 * @category constructors
 */
export const multimodal = (shape) => {
    let cached = null;
    return {
        _effectGolem: "Multimodal",
        shape,
        compile: () => Effect.suspend(() => {
            if (cached !== null)
                return Effect.succeed(cached);
            return Effect.gen(function* () {
                const cases = [];
                for (const [k, m] of Object.entries(shape)) {
                    cases.push((yield* compileMember(k, m)));
                }
                const byName = new Map(cases.map((c, i) => [c.name, { c, index: i }]));
                const composed = composeSchemaGraphs(cases.map((member) => member.graph));
                const variantCases = cases.map((c, index) => variantCase(c.name, composed.roots[index]));
                const variant = t.variant(variantCases);
                const root = {
                    body: t.list(variant).body,
                    metadata: { ...emptyMetadata(), role: MULTIMODAL_ROLE },
                };
                const toValue = (value) => Effect.gen(function* () {
                    const elements = [];
                    for (const item of value) {
                        const entry = byName.get(item._tag);
                        if (entry === undefined) {
                            throw new Error(`multimodal: unknown case '${item._tag}'`);
                        }
                        elements.push(v.variant(entry.index, yield* entry.c.toValue(item.value)));
                    }
                    return v.list(elements);
                });
                const fromValue = (sv) => Effect.gen(function* () {
                    if (sv.tag !== "list") {
                        throw new Error(`multimodal: expected a list value, got ${sv.tag}`);
                    }
                    const out = [];
                    for (const el of sv.elements) {
                        if (el.tag !== "variant") {
                            throw new Error(`multimodal: expected variant element, got ${el.tag}`);
                        }
                        const c = cases[el.caseIndex];
                        if (c === undefined) {
                            throw new Error(`multimodal: unknown case index ${el.caseIndex}`);
                        }
                        if (el.payload === undefined) {
                            throw new Error(`multimodal: missing payload for case '${c.name}'`);
                        }
                        out.push({ _tag: c.name, value: yield* c.fromValue(el.payload) });
                    }
                    return out;
                });
                const SchemaValueCarrier = Schema.declare((_u) => true);
                const DomainCarrier = Schema.declare((_u) => true);
                const codec = SchemaValueCarrier.pipe(Schema.decodeTo(DomainCarrier, {
                    decode: SchemaGetter.transformEffect((sv) => fromValue(sv).pipe(Effect.mapError((error) => error.issue))),
                    encode: SchemaGetter.transformEffect((d) => toValue(d).pipe(Effect.mapError((error) => error.issue))),
                }));
                cached = {
                    schema: DomainCarrier,
                    graph: { defs: composed.defs, root },
                    isUnit: false,
                    codec,
                };
                return cached;
            });
        }),
    };
};
/**
 * Type-guard for `Multimodal` carriers.
 *
 * @since 1.5.0
 * @category guards
 */
export const isMultimodal = (x) => typeof x === "object" &&
    x !== null &&
    x._effectGolem === "Multimodal";
// ---------- Convenience constructors ----------
/**
 * Multimodal payload with arbitrary text + image elements.
 *
 * @since 1.5.0
 * @category constructors
 */
export const multimodalTextImage = (opts) => multimodal({
    text: UnstructuredText(opts?.text),
    image: UnstructuredBinary(opts?.image),
});
/**
 * Multimodal payload with arbitrary text + image elements plus a custom
 * schema under a named slot (default: `"custom"`).
 *
 * @since 1.5.0
 * @category constructors
 */
export const multimodalTextImageCustom = (custom, opts) => {
    const name = opts?.customName ?? "custom";
    const shape = {
        text: UnstructuredText(opts?.text),
        image: UnstructuredBinary(opts?.image),
        [name]: custom,
    };
    return multimodal(shape);
};
