import { Context, Layer } from "effect";
import * as RevealHost from "golem:secrets/reveal@0.1.0";
import * as SecretsHost from "golem:secrets/types@0.1.0";
export class SecretsClient extends Context.Service()("effect-golem/host/Secrets") {
}
export const SecretsLive = Layer.succeed(SecretsClient, SecretsClient.of({
    reveal: RevealHost.reveal,
    id: SecretsHost.id,
    metadata: SecretsHost.metadata,
}));
