import { Context, Effect, Schema, SchemaAST } from "effect";
import { t } from "./internal/schema-model/model.js";
import { schemaGraphToWit } from "./internal/schema-model/wit.js";
import { compile, UnsupportedSchemaError } from "./WitCodec.js";
import { compiledConfigRuntime } from "./internal/compiledConfig.js";
export class ConfigError {
    path;
    reason;
    _tag = "ConfigError";
    constructor(path, reason) {
        this.path = path;
        this.reason = reason;
    }
}
const redactedInner = (schema) => {
    const ast = schema.ast;
    if (ast._tag !== "Declaration")
        return undefined;
    const id = ast.annotations?.representation
        ?.id;
    return id === "effect/schema/Redacted" && ast.typeParameters[0] !== undefined
        ? Schema.make(ast.typeParameters[0])
        : undefined;
};
const objectAst = (ast) => {
    if (SchemaAST.isObjects(ast) && ast.indexSignatures.length === 0)
        return { ast, optional: false };
    if (ast._tag === "Union" && ast.context?.isOptional === true) {
        const object = ast.types.find(SchemaAST.isObjects);
        if (object !== undefined && object.indexSignatures.length === 0)
            return { ast: object, optional: true };
    }
    return undefined;
};
export const compileConfig = (fields, contextLabel) => Effect.gen(function* () {
    const leaves = [];
    const branches = new Set();
    const visit = (schema, path, underOptional, required) => Effect.gen(function* () {
        const inner = redactedInner(schema);
        if (inner !== undefined) {
            const valueSchema = underOptional ? Schema.UndefinedOr(inner) : inner;
            const codec = (yield* compile(valueSchema));
            const declarationGraph = { defs: codec.graph.defs, root: t.secret(codec.graph.root) };
            leaves.push({
                source: "secret",
                path,
                schema: valueSchema,
                codec,
                declarationGraph,
                required: true,
            });
            return;
        }
        const object = objectAst(schema.ast);
        if (object !== undefined) {
            branches.add(path.join("/"));
            for (const property of object.ast.propertySignatures) {
                if (typeof property.name !== "string") {
                    return yield* Effect.fail(new UnsupportedSchemaError(`${contextLabel}: config object keys must be strings`));
                }
                const optional = property.type.context?.isOptional === true;
                yield* visit(Schema.make(property.type), [...path, property.name], underOptional || object.optional, !optional);
            }
            return;
        }
        let codec = (yield* compile(schema));
        let valueSchema = schema;
        if (underOptional && codec.graph.root.body.tag !== "option") {
            const optionalSchema = Schema.UndefinedOr(schema);
            valueSchema = optionalSchema;
            codec = (yield* compile(optionalSchema));
        }
        leaves.push({
            source: "local",
            path,
            schema: valueSchema,
            codec,
            declarationGraph: codec.graph,
            required,
        });
    });
    for (const [name, schema] of Object.entries(fields))
        yield* visit(schema, [name], false, true);
    const leavesByPath = new Map(leaves.map((leaf) => [leaf.path.join("/"), leaf]));
    return {
        graphs: leaves.map((leaf) => leaf.declarationGraph),
        leaves,
        leavesByPath,
        branches,
        declarations: (indices) => {
            if (indices.length !== leaves.length)
                throw new Error("config declaration index count mismatch");
            return leaves.map((leaf, i) => ({
                source: leaf.source,
                path: [...leaf.path],
                valueType: indices[i],
            }));
        },
        buildShape: compiledConfigRuntime(leaves.map((leaf) => ({
            ...leaf,
            declarationSchema: schemaGraphToWit(leaf.declarationGraph),
        })), branches).buildShape,
    };
});
export const defineConfig = (name, fields) => {
    class Base extends Context.Service()(name) {
        static fields = fields;
        static __cfgTag = undefined;
        static __fields = fields;
        static cached = null;
        static __compile() {
            return Effect.suspend(() => Base.cached === null
                ? Effect.tap(compileConfig(fields, name), (value) => Effect.sync(() => (Base.cached = value)))
                : Effect.succeed(Base.cached));
        }
    }
    return Base;
};
export const encodeOverrides = (compiled, overrides) => Effect.gen(function* () {
    const out = [];
    const visit = (value, path) => Effect.gen(function* () {
        const key = path.join("/");
        const leaf = compiled.leavesByPath.get(key);
        if (leaf === undefined) {
            if (compiled.branches.has(key) && typeof value === "object" && value !== null) {
                for (const [name, child] of Object.entries(value))
                    yield* visit(child, [...path, name]);
                return;
            }
            return yield* Effect.fail(new ConfigError(path, {
                _tag: "Unsupported",
                reason: `unknown override path: ${path.join(".")}`,
            }));
        }
        if (leaf.source === "secret") {
            return yield* Effect.fail(new ConfigError(path, {
                _tag: "Unsupported",
                reason: `cannot override secret config path: ${path.join(".")}`,
            }));
        }
        out.push({
            path: [...path],
            value: {
                graph: leaf.codec.schemaGraph,
                value: yield* leaf.codec.encode(value),
            },
        });
    });
    for (const [name, value] of Object.entries(overrides))
        yield* visit(value, [name]);
    return out;
});
