export const invokeMethod = (codec, handler, input) => invokeWireValue(codec.inputCodec, codec.encodeOutput, {
    errorWrapped: codec.errorWrapped,
    successVoid: codec.successVoid,
    inputSchema: codec.inputSchema,
}, handler, input);
